-- Q1 what is the total revenue generated by male vs female customers ?
select 
		gender,
		sum(purchase_amount) as revenue
from customer_shopping_behavior group by gender;

-- Q2 which customer used discount but still spent more than the average purchase amount ?
select 
		customer_id,
		purchase_amount
from customer_shopping_behavior 
where discount_applied='Yes' and purchase_amount >(select avg(purchase_amount) from customer_shopping_behavior);

--Q3 which are the top 5 products with the highest average review rating ?
select 
		item_purchased,
		round(cast(avg(review_rating) as decimal),2) as average_rating
from customer_shopping_behavior 
group by item_purchased
order by average_rating desc limit 5;

--Q4 compare the average purchase amounts between standard and express shipping
select 
		shipping_type,
		round(cast(avg(purchase_amount) as decimal),2) as average_purchase_amount
from customer_shopping_behavior
where shipping_type in('Express','Standard')
group by shipping_type;

--Q5 do subscribed customers spend more? compare average spend 
--and total revenue between subscribers and non-subscribers
select
		subscription_status,
		count(customer_id) as total_customers,
		round(cast(avg(purchase_amount) as decimal),2) as average_spend,
		sum(purchase_amount) as total_revenue
from customer_shopping_behavior
group by subscription_status;

--Q6 which 5 products have the highest percentage of purchases with discounts applied
select
		item_purchased,
		round(100.0*sum(case when discount_applied='Yes' then 1 else 0 end)/count(*),2) as discount_rate
from customer_shopping_behavior
group by item_purchased
order by discount_rate desc
limit 5;

--Q7 segment customers into new, returning, and loyal based on their total 
--number of previous purchases , and show the count of each segment
select
		(case 
			when previous_purchases=1 then 'new_customers'
			when previous_purchases between 2 and 10 then 'returning_customers'
			when previous_purchases > 10 then 'loyal_customers'
		end) as customer_segment,
		count(*) as number_of_customers
from customer_shopping_behavior
group by customer_segment;

--Q8 what are the top 3 most purchased products within each category
with item_ranking as(select
		category,
		item_purchased,
		count(customer_id) as total_orders,
		row_number() over(partition by category order by count(customer_id) desc) as item_rank
from customer_shopping_behavior
group by category,item_purchased)

select item_rank,
		category,
		item_purchased,
		total_orders
from item_ranking
where item_rank <=3;

--Q9 are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
select
		subscription_status,
		count(customer_id) as repeat_buyer
from customer_shopping_behavior
where previous_purchases > 5
group by  subscription_status;

--Q10 what is the revenue contribution of each age group ?
select
		age_group,
		sum(purchase_amount) as total_revenue
from customer_shopping_behavior
group by age_group
order by total_revenue desc;







